import{_ as t,c as a,o as i,ag as o}from"./chunks/framework.DRADY2L-.js";const u=JSON.parse('{"title":"Buddai Web Server","description":"","frontmatter":{},"headers":[],"relativePath":"web_server/index.md","filePath":"web_server/index.md"}'),r={name:"web_server/index.md"};function d(s,e,n,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="buddai-web-server" tabindex="-1">Buddai Web Server <a class="header-anchor" href="#buddai-web-server" aria-label="Permalink to &quot;Buddai Web Server&quot;">​</a></h1><p>Express-based REST back end that powers the Buddai console and integrations. It handles authentication, agent metadata, model registry, environment variables, and bridges to external messaging providers (WhatsApp, Telegram) plus calendar/agenda synchronisation.</p><h2 id="functional-overview" tabindex="-1">Functional Overview <a class="header-anchor" href="#functional-overview" aria-label="Permalink to &quot;Functional Overview&quot;">​</a></h2><ul><li><p><strong>Authentication &amp; Security</strong></p><ul><li><code>/login</code> endpoint validates MongoDB credentials and returns AES-encrypted JWTs.</li><li><code>authMiddleware</code> decrypts/verifies tokens before granting access to protected routes.</li><li>Configuration of JWT/AES secrets and expiry via environment variables.</li></ul></li><li><p><strong>Agent Management API</strong> (<code>/agents</code>)</p><ul><li>Lists agent definitions loaded from <code>agents/*.agent.yml</code> on startup.</li><li>Supports CRUD operations for UI workflows (create, update, delete).</li><li>Dynamically regenerates IDs and merges updates.</li></ul></li><li><p><strong>Models API</strong> (<code>/models</code>)</p><ul><li>Exposes available LLM models and MCP service metadata for the front-end.</li></ul></li><li><p><strong>Environment Variables API</strong> (<code>/environment_vars</code>)</p><ul><li>Surfaces configured environment variables, marking secrets for UI masking.</li><li>Allows updates (in-memory) for quick prototyping and UI adjustments.</li></ul></li><li><p><strong>Location API</strong> (<code>/location</code>)</p><ul><li>Proxy endpoints for reading/updating the current user location.</li></ul></li><li><p><strong>Messaging Bridges</strong></p><ul><li><strong>WhatsApp</strong> (<code>/whatsapp/status</code>) – QR-based pairing UI + status page; inbound messages routed through Baileys client.</li><li><strong>Telegram</strong> (<code>/telegram</code>) – Simple send/edit wrappers around Telegram Bot API.</li></ul></li><li><p><strong>Agenda &amp; Calendar Integration</strong></p><ul><li><code>agendaService</code> manages cron-like reminders via Agenda/MongoDB.</li><li><code>syncCalendarService</code> coordinates calendar synchronisation with downstream MCPs.</li></ul></li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><code>index.js</code> – Express bootstrap, route wiring, service lifecycle (WhatsApp, agenda, sync).</li><li><code>src/routes/</code> – HTTP controllers: <ul><li><code>web/loginController</code>, <code>web/agentsController</code>, <code>web/modelsController</code> for UI API.</li><li><code>whatsappController</code>, <code>telegramController</code>, <code>locationController</code>, <code>environmentVarsController</code> for external integrations.</li></ul></li><li><code>src/services/</code> – Core business logic (agents, agenda, messaging, syncing, supervisor calls).</li><li><code>src/clients/</code> – Client adapters (e.g., Baileys WhatsApp client).</li><li><code>src/helpers/</code> – Utility helpers for message parsing, env var formatting.</li></ul><h2 id="setup-configuration" tabindex="-1">Setup &amp; Configuration <a class="header-anchor" href="#setup-configuration" aria-label="Permalink to &quot;Setup &amp; Configuration&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Node.js ≥ 20.x</li><li>MongoDB instance reachable from the server.</li><li>WhatsApp device for QR pairing (optional).</li><li>Telegram bot token (optional).</li></ul><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th><th>Default</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>Server port</td><td><code>8025</code></td></tr><tr><td><code>MONGO_HOST</code></td><td>MongoDB host for login verification</td><td><code>localhost</code></td></tr><tr><td><code>JWT_SECRET</code></td><td>JWT signing secret</td><td><code>buddai_supersecret</code></td></tr><tr><td><code>JWT_EXPIRY</code></td><td>JWT expiration</td><td><code>100y</code></td></tr><tr><td><code>AES_SECRET</code></td><td>AES encryption key for tokens</td><td><code>buddai_aes256key</code></td></tr><tr><td><code>TELEGRAM_BOT_TOKEN</code></td><td>Token for Telegram API</td><td><em>required for Telegram</em></td></tr><tr><td><code>WHATSAPP_*</code></td><td>Credentials/configuration consumed by Baileys</td><td><em>as needed</em></td></tr><tr><td><code>SYNC_*</code></td><td>Calendar sync configuration</td><td><em>as needed</em></td></tr></tbody></table><p>Ensure MongoDB has users matching login attempts (<code>username/password</code>); the server tests credentials by connecting to <code>mongodb://username:password@MONGO_HOST:27017/username</code>.</p><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h3 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><ul><li>Consider using <code>DEBUG=web-server:*</code> to view detailed logs.</li><li>Pair WhatsApp via <code>/whatsapp/status</code> QR page after server starts.</li></ul><h3 id="production" tabindex="-1">Production <a class="header-anchor" href="#production" aria-label="Permalink to &quot;Production&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # optional: bundle/static assets if needed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.js</span></span></code></pre></div><ul><li>Use process managers (PM2, systemd) to supervise the service.</li><li>Configure environment variables and secrets via deployment platform.</li></ul><h2 id="api-summary" tabindex="-1">API Summary <a class="header-anchor" href="#api-summary" aria-label="Permalink to &quot;API Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method(s)</th><th>Description</th><th>Auth</th></tr></thead><tbody><tr><td><code>/login</code></td><td>POST</td><td>Validate MongoDB credentials and issue token</td><td>Public</td></tr><tr><td><code>/agents</code></td><td>GET/POST/PUT/DELETE</td><td>Manage agent definitions</td><td>Protected</td></tr><tr><td><code>/models</code></td><td>GET</td><td>List available models</td><td>Protected</td></tr><tr><td><code>/environment_vars</code></td><td>GET/PUT</td><td>View/update env vars cache</td><td>Protected</td></tr><tr><td><code>/location</code></td><td>GET/POST</td><td>Manage user location</td><td>Public</td></tr><tr><td><code>/whatsapp/status</code></td><td>GET</td><td>Status/QR page for WhatsApp bridge</td><td>Public</td></tr><tr><td><code>/telegram/send</code> etc.</td><td>POST</td><td>Telegram messaging helpers</td><td>Public/Protected (depending on route)</td></tr></tbody></table><p>All protected routes require <code>Authorization: Bearer &lt;encrypted-token&gt;</code> header (token from <code>/login</code>).</p><h2 id="messaging-workflow" tabindex="-1">Messaging Workflow <a class="header-anchor" href="#messaging-workflow" aria-label="Permalink to &quot;Messaging Workflow&quot;">​</a></h2><ul><li>WhatsApp inbound messages → <code>whatsappService</code> → <code>processIncomingMessage</code> helper → <code>callSupervisor</code> (MCP supervisor) → responses returned via Baileys.</li><li>Telegram outbound messages use fetch calls against Telegram Bot API (<code>sendMessage</code>, <code>editMessageText</code>).</li></ul><h2 id="calendar-agenda" tabindex="-1">Calendar &amp; Agenda <a class="header-anchor" href="#calendar-agenda" aria-label="Permalink to &quot;Calendar &amp; Agenda&quot;">​</a></h2><ul><li>Agenda jobs persisted in MongoDB for reminders.</li><li>Sync service orchestrates calendar updates; ensure required MCP services are reachable.</li></ul><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><ul><li><code>Dockerfile</code> builds the service with Node 22, copies dependencies, and exposes port <code>8025</code>.</li><li>Use <code>docker build -t buddai/web-server web_server</code> to create an image.</li><li>Compose with other stack services using provided docker-compose files.</li></ul><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><ul><li>Uses <code>debug</code> namespaces (<code>web-server:*</code>).</li><li>Enable via <code>DEBUG=web-server:*</code> or more granular selectors.</li></ul><h2 id="roadmap-ideas" tabindex="-1">Roadmap Ideas <a class="header-anchor" href="#roadmap-ideas" aria-label="Permalink to &quot;Roadmap Ideas&quot;">​</a></h2><ul><li>Harden login flow with rate limiting/captcha.</li><li>Persist environment variable edits to backing store.</li><li>Add WebSocket/SSE for realtime supervisor updates.</li><li>Expand Telegram router with webhooks and inbound handling.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>Internal Buddai project. Reach out to maintainers for usage or redistribution guidance.</p>`,35)])])}const g=t(r,[["render",d]]);export{u as __pageData,g as default};
